type ToArrayDist<T> = T extends any ? T[] : never;
type R1 = ToArrayDist<string | number>;
// string[] | number[] — distributed

type ToArrayNonDist<T> = [T] extends [any] ? T[] : never;
type R2 = ToArrayNonDist<string | number>;
// (string | number)[] — whole union wrapped

type MyExclude<T, U> = T extends U ? never : T;

type All = 'GET' | 'POST' | 'DELETE';
type ReadOnly = MyExclude<All, 'DELETE'>;
// 'GET' | 'POST'

// Step: 'GET' extends 'DELETE'? never : 'GET' | ...

type Routes = {
  '/users': { method: 'GET'; res: User[] };
  '/users/:id': { method: 'GET'; res: User };
  '/users/:id': { method: 'DELETE'; res: void };
};

type MethodFor<Path extends keyof Routes, M> =
  Routes[Path] extends { method: M } ? M : never;

type GetPaths<P extends keyof Routes> = P extends any
  ? MethodFor<P, 'GET'> extends never ? never : P
  : never;
// distributive filter over paths

type Pair<T> = T extends any ? [T, T] : never;
type Bad = Pair<string | number>;
// [string, string] | [number, number] — not [string|number, string|number]
